async function loadWeather(){state.weather.clear();const t=today(),max=isoDate(addDays(new Date(),15)),start=state.rangeStart<t?t:state.rangeStart,end=state.rangeEnd>max?max:state.rangeEnd;if(start<=end)try{const q=new URLSearchParams({latitude:LAT,longitude:LON,daily:"weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",timezone:"America/Sao_Paulo",start_date:start,end_date:end}),r=await fetch(`https://api.open-meteo.com/v1/forecast?${q}`),d=await r.json();(d.daily?.time||[]).forEach((date,i)=>state.weather.set(date,{code:d.daily.weather_code[i],max:Math.round(d.daily.temperature_2m_max[i]),min:Math.round(d.daily.temperature_2m_min[i]),precip:d.daily.precipitation_probability_max[i]??0}))}catch(e){console.warn(e)}updateWeatherUI();renderCalendar();renderToday()}
