async function initOnline(){state.supabase=window.supabase.createClient(CONFIG.SUPABASE_URL,CONFIG.SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const{data}=await state.supabase.auth.getSession();state.session=data.session;state.user=data.session?.user||null;state.supabase.auth.onAuthStateChange((_e,s)=>{state.session=s;state.user=s?.user||null});if(!state.user)return showOnly("#authScreen");await loadBoards()}
