function subscribeRealtime(){if(state.mode!=="online"||!state.board)return;if(state.realtimeChannel)state.supabase.removeChannel(state.realtimeChannel);const tables=["day_plans","shared_tasks","shared_task_occurrences","shared_task_exceptions","finance_entries","recurring_bills","recurring_bill_payments","shopping_items","pet_care_logs","pet_health_records","goals","inventory_items","notices","notice_reads","availability_blocks","plan_checklist_items","plan_participants","board_members"],ch=state.supabase.channel(`v5-${state.board.id}`);tables.forEach(table=>ch.on("postgres_changes",{event:"*",schema:"public",table,filter:`board_id=eq.${state.board.id}`},async p=>{const newNotice=table==="notices"&&p.eventType==="INSERT"&&p.new?.created_by!==state.user.id;await refreshAll(false);if(newNotice){toast(`💌 Novo recado: ${p.new.title}`);if("Notification"in window&&Notification.permission==="granted")new Notification("Nosso Tempo 💌",{body:p.new.title});showUnreadNotices()}}));state.realtimeChannel=ch.subscribe()}
