function plansOn(date){return state.plans.filter(p=>p.plan_date===date).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"))}
function renderCalendar(){if(!state.rangeStart)return;updateRangeLabel();const dates=getRangeDates(state.rangeStart,state.rangeEnd),first=parseDate(state.rangeStart),blanks=(first.getDay()+6)%7;let html=Array.from({length:blanks},()=>`<div class="blank-day"></div>`).join("");for(const date of dates){const d=parseDate(date),w=state.weather.get(date),plans=plansOn(date),show=plans.slice(0,4);html+=`<article class="day-card ${date===today()?"today":""}" data-date="${date}"><div class="day-head"><span class="day-number"><strong>${d.getDate()}</strong><small>${d.toLocaleDateString("pt-BR",{weekday:"short"}).replace(".","")}</small></span>${w?`<span class="weather-mini">${weatherIcon(w.code)} <span>${w.max}° • ${w.precip}%</span></span>`:`<span class="weather-mini">🗓️ <span>—</span></span>`}</div><div class="day-events">${show.map(p=>{const s=effectivePlanStatus(p),opt=p.selected_option==="bad"?p.bad_option:p.selected_option==="good"?p.good_option:(p.good_option||p.bad_option||"");return`<button class="event-chip ${s}" data-plan-id="${p.id}" style="border-left-color:${memberColor(p.chooser_user_id)}"><span class="event-topline">${p.start_time?String(p.start_time).slice(0,5):"sem hora"}${p.end_time?`–${String(p.end_time).slice(0,5)}`:""} • ${esc(memberName(p.chooser_user_id))}</span><span class="event-title">${s==="done"?"✓ ":s==="unexpected"?"⚡ ":s==="missed"?"○ ":""}${esc(p.title||"Atividade")}</span>${opt?`<span class="event-option">${esc(opt)}</span>`:""}</button>`}).join("")}${plans.length>4?`<span class="more-events">+${plans.length-4}</span>`:""}</div></article>`}$("#calendarGrid").innerHTML=html;const r=state.plans.filter(p=>inRange(p.plan_date)),done=r.filter(p=>effectivePlanStatus(p)==="done").length,miss=r.filter(p=>effectivePlanStatus(p)==="missed").length;$("#calendarQuickStat").textContent=`${done} realizados`;$("#calendarQuickSub").textContent=miss?`${miss} não realizado(s).`:"Tudo em dia."}
function openDay(date){state.activeDate=date;$("#dayDialogWeekday").textContent=weekDay(date).toUpperCase();$("#dayDialogDate").textContent=longDate(date);const w=state.weather.get(date);$("#dayDialogWeather").innerHTML=w?`${weatherIcon(w.code)} <strong>${w.max}° / ${w.min}°</strong> • ${w.precip}% chuva`:`🗓️ Previsão ainda indisponível.`;const p=plansOn(date);$("#dayPlanList").innerHTML=p.length?p.map(x=>{const s=effectivePlanStatus(x);return`<article class="day-plan-card"><button class="circle-check ${s==="done"?"checked":s==="unexpected"?"unexpected":""}" data-quick-plan="${x.id}">${s==="done"?"✓":s==="unexpected"?"⚡":""}</button><div class="plan-copy"><div class="plan-title">${esc(x.title)}</div><div class="plan-meta">${x.start_time?String(x.start_time).slice(0,5):"sem hora"}${x.end_time?`–${String(x.end_time).slice(0,5)}`:""} • ${statusText(s)}</div></div><button class="icon-mini" data-edit-plan="${x.id}">✎</button></article>`}).join(""):`<div class="empty-state">Nenhuma atividade ainda.</div>`;openDialog("#dayDialog")}
function participantIds(id){const r=state.planParticipants.filter(x=>x.plan_id===id);return r.length?r.map(x=>x.user_id):state.members.map(m=>m.user_id)}
function selectedParticipants(){return $$("[data-participant]:checked").map(x=>x.dataset.participant)}
function intervalsOverlap(a1,a2,b1,b2){if(!a1||!b1)return false;a2=a2||a1;b2=b2||b1;return a1<b2&&b1<a2}
function availabilityFor(uid,date,start,end,ignorePlan=null){if(!start)return[{type:"unknown",text:"escolha um horário"}];const wd=parseDate(date).getDay(),blocks=state.availability.filter(b=>b.user_id===uid&&(b.specific_date===date||(!b.specific_date&&Number(b.weekday)===wd))),messages=[];for(const b of blocks){if(b.availability_type==="busy"&&intervalsOverlap(start,end||start,String(b.start_time).slice(0,5),String(b.end_time).slice(0,5)))messages.push({type:"busy",text:`ocupado — ${b.label} (${String(b.start_time).slice(0,5)}–${String(b.end_time).slice(0,5)})`})}const explicitAvailable=blocks.filter(b=>b.availability_type==="available");if(explicitAvailable.length&&!explicitAvailable.some(b=>intervalsOverlap(start,end||start,String(b.start_time).slice(0,5),String(b.end_time).slice(0,5))))messages.push({type:"busy",text:"fora do período marcado como disponível"});for(const p of plansOn(date)){if(p.id===ignorePlan)continue;if(!participantIds(p.id).includes(uid))continue;if(intervalsOverlap(start,end||start,String(p.start_time||"").slice(0,5),String(p.end_time||p.start_time||"").slice(0,5)))messages.push({type:"busy",text:`conflito com "${p.title}" (${String(p.start_time||"").slice(0,5)}–${String(p.end_time||p.start_time||"").slice(0,5)})`})}return messages.length?messages:[{type:blocks.length?"available":"unknown",text:blocks.length?"sem conflito":"sem disponibilidade cadastrada"}]}
function updateAvailabilityWarning(){const start=$("#planTime").value,end=$("#planEndTime").value,ids=selectedParticipants();$("#availabilityWarning").innerHTML=ids.flatMap(id=>availabilityFor(id,state.activeDate,start,end,state.editingPlanId).map(a=>`<div class="availability-status ${a.type}"><strong>${esc(memberName(id))}:</strong> ${esc(a.text)}</div>`)).join("")}
function openPlan(id=null,date=state.activeDate||today()){const p=id?state.plans.find(x=>x.id===id):null;state.editingPlanId=id;state.activeDate=p?.plan_date||date;$("#dialogWeekday").textContent=weekDay(state.activeDate).toUpperCase();$("#dialogDate").textContent=longDate(state.activeDate);const w=state.weather.get(state.activeDate);$("#dialogWeather").innerHTML=w?`${weatherIcon(w.code)} ${w.max}° / ${w.min}° • ${w.precip}% chuva`:"🗓️ Sem previsão.";$("#planTitle").value=p?.title||"";$("#chooserSelect").value=p?.chooser_user_id||"";$("#category").value=p?.category||"💛 Tempo juntos";$("#planTime").value=p?.start_time?String(p.start_time).slice(0,5):"";$("#planEndTime").value=p?.end_time?String(p.end_time).slice(0,5):"";$("#goodOption").value=p?.good_option||"";$("#badOption").value=p?.bad_option||"";$("#selectedOption").value=p?.selected_option||"auto";$("#notes").value=p?.notes||"";$("#incidentReason").value=p?.incident_reason||"";$("#activityDone").checked=p?.status==="done";$("#activityUnexpected").checked=p?.status==="unexpected";$("#incidentReasonWrap").classList.toggle("hidden",!$("#activityUnexpected").checked);let rem="";if(p?.reminder_at){const d=new Date(p.reminder_at),l=new Date(d.getTime()-d.getTimezoneOffset()*60000);rem=l.toISOString().slice(0,16)}$("#reminderAt").value=rem;const selected=new Set(p?participantIds(p.id):state.members.map(m=>m.user_id));$("#participantChecks").innerHTML=state.members.map(m=>`<label class="participant-pill"><input type="checkbox" data-participant="${m.user_id}" ${selected.has(m.user_id)?"checked":""}/><span class="member-color" style="background:${m.profile_color||"#df8f7c"}"></span>${esc(m.display_name)}</label>`).join("");state.editChecklist=p?state.planChecklist.filter(x=>x.plan_id===p.id).map(x=>({...x})):[];renderPlanChecklist();$("#deletePlan").style.visibility=p?"visible":"hidden";closeDialog("#dayDialog");openDialog("#planDialog");updateAvailabilityWarning()}
function renderPlanChecklist(){$("#planChecklistList").innerHTML=state.editChecklist.length?state.editChecklist.map((x,i)=>`<div class="mini-check-item"><input type="checkbox" data-plan-check="${i}" ${x.is_done?"checked":""}/><span>${esc(x.item_text)}</span><button type="button" data-remove-plan-check="${i}">×</button></div>`).join(""):`<p class="muted tiny">Sem subtarefas.</p>`}
async function savePlan(e){e.preventDefault();const start=$("#planTime").value,end=$("#planEndTime").value;if(start&&end&&end<=start)return toast("O horário final precisa ser depois do início.");const payload={board_id:state.board.id,plan_date:state.activeDate,title:$("#planTitle").value.trim(),chooser_user_id:$("#chooserSelect").value||null,category:$("#category").value,good_option:$("#goodOption").value.trim()||null,bad_option:$("#badOption").value.trim()||null,start_time:start||null,end_time:end||null,selected_option:$("#selectedOption").value,status:$("#activityUnexpected").checked?"unexpected":$("#activityDone").checked?"done":"planned",reminder_at:$("#reminderAt").value?new Date($("#reminderAt").value).toISOString():null,notes:$("#notes").value.trim()||null,incident_reason:$("#incidentReason").value.trim()||null,updated_by:state.user.id,updated_at:new Date().toISOString()};if(!payload.title)return toast("Dê um nome para a atividade.");let id=state.editingPlanId;if(state.mode==="demo"){if(id)Object.assign(state.plans.find(x=>x.id===id),payload);else{id=crypto.randomUUID();state.plans.push({...payload,id,created_by:state.user.id,created_at:new Date().toISOString()})}state.planParticipants=state.planParticipants.filter(x=>x.plan_id!==id);selectedParticipants().forEach(uid=>state.planParticipants.push({plan_id:id,user_id:uid}));state.planChecklist=state.planChecklist.filter(x=>x.plan_id!==id);state.editChecklist.forEach((x,i)=>state.planChecklist.push({id:crypto.randomUUID(),plan_id:id,item_text:x.item_text,is_done:x.is_done,position:i}));demoSave()}else{const r=id?await state.supabase.from("day_plans").update(payload).eq("id",id).select().single():await state.supabase.from("day_plans").insert({...payload,created_by:state.user.id}).select().single();if(r.error)return toast(r.error.message);id=r.data.id;await state.supabase.from("plan_participants").delete().eq("plan_id",id);const parts=selectedParticipants();if(parts.length)await state.supabase.from("plan_participants").insert(parts.map(uid=>({board_id:state.board.id,plan_id:id,user_id:uid})));await state.supabase.from("plan_checklist_items").delete().eq("plan_id",id);if(state.editChecklist.length)await state.supabase.from("plan_checklist_items").insert(state.editChecklist.map((x,i)=>({board_id:state.board.id,plan_id:id,item_text:x.item_text,is_done:x.is_done,position:i})));await refreshAll(false)}closeDialog("#planDialog");renderAll();toast("Atividade salva ♡")}
async function deletePlan(){const id=state.editingPlanId;if(!id)return;if(state.mode==="demo"){state.plans=state.plans.filter(x=>x.id!==id);state.planChecklist=state.planChecklist.filter(x=>x.plan_id!==id);state.planParticipants=state.planParticipants.filter(x=>x.plan_id!==id);demoSave()}else{await state.supabase.from("day_plans").delete().eq("id",id);await refreshAll(false)}closeDialog("#planDialog");renderAll()}
async function quickPlan(id){const p=state.plans.find(x=>x.id===id),next=p.status==="done"?"planned":"done";if(state.mode==="demo"){p.status=next;demoSave();renderAll();if($("#dayDialog").open)openDay(p.plan_date)}else{await state.supabase.from("day_plans").update({status:next,updated_at:new Date().toISOString()}).eq("id",id);await refreshAll(false);if($("#dayDialog").open)openDay(p.plan_date)}}

function isRecurringTask(t){return(t.recurrence_type||"none")!=="none"}
function recurrenceStart(t){return t.recurrence_start||t.due_date||String(t.created_at||today()).slice(0,10)}
function taskException(t,date){return state.taskExceptions.find(x=>x.task_id===t.id&&x.exception_date===date)}
function taskOccursOn(t,date){if(taskException(t,date))return false;if(!isRecurringTask(t))return t.due_date===date;const start=recurrenceStart(t);if(date<start||t.recurrence_end&&date>t.recurrence_end)return false;const d=parseDate(date),s=parseDate(start),wd=d.getDay(),type=t.recurrence_type;if(type==="daily")return true;if(type==="weekdays")return wd>=1&&wd<=5;if(type==="weekly")return wd===s.getDay();if(type==="custom_weekdays")return(t.recurrence_weekdays||[]).map(Number).includes(wd);if(type==="monthly")return d.getDate()===s.getDate();return false}
function taskOccurrence(t,date){return state.taskOccurrences.find(x=>x.task_id===t.id&&x.occurrence_date===date)}
function occurrenceStatus(t,date){if(!isRecurringTask(t))return effectiveTaskStatus(t);const o=taskOccurrence(t,date);if(o?.is_done)return"done";if(o?.unforeseen)return"unexpected";if(date<today())return"missed";return"planned"}
function recurrenceText(t){const d=parseDate(recurrenceStart(t)),type=t.recurrence_type;if(type==="daily")return"Todos os dias";if(type==="weekdays")return"Segunda a sexta";if(type==="weekly")return`Toda ${WEEKDAYS[d.getDay()].toLowerCase()}`;if(type==="custom_weekdays")return`Toda semana: ${(t.recurrence_weekdays||[]).map(Number).map(x=>WEEKDAYS[x].slice(0,3)).join(", ")}`;if(type==="monthly")return`Todo dia ${d.getDate()}`;return"Não repete"}
function recurrenceDates(t,from,to){const a=[];let d=parseDate(from),last=parseDate(to),g=0;while(d<=last&&g<400){const s=isoDate(d);if(taskOccursOn(t,s))a.push(s);d=addDays(d,1);g++}return a}
function nextOccurrence(t,from=today()){if(!isRecurringTask(t))return t.due_date;let d=parseDate(from);for(let i=0;i<370;i++){const s=isoDate(d);if(taskOccursOn(t,s))return s;d=addDays(d,1)}return null}
function taskInstances(from,to){const rows=[];for(const t of state.tasks){if(isRecurringTask(t)){for(const d of recurrenceDates(t,from,to))rows.push({task:t,date:d,status:occurrenceStatus(t,d)})}else{const d=t.due_date||String(t.created_at||today()).slice(0,10);if(d>=from&&d<=to)rows.push({task:t,date:d,status:effectiveTaskStatus(t)})}}return rows}
function selectedRecurDays(){return $$("[data-recur-day]:checked").map(x=>Number(x.dataset.recurDay))}
function updateRecurrenceUI(){const type=$("#taskRecurrence").value,rec=type!=="none";$("#recurrenceEndWrap").classList.toggle("hidden",!rec);$("#customWeekdaysWrap").classList.toggle("hidden",type!=="custom_weekdays");$("#routineExceptionsWrap").classList.toggle("hidden",!rec);$("#singleTaskStatus").classList.toggle("hidden",rec);$("#recurringStatusHint").classList.toggle("hidden",!rec);const d=parseDate($("#taskDueDate").value||today()),days=selectedRecurDays().map(x=>WEEKDAYS[x].slice(0,3));let text="";if(type==="daily")text="Todos os dias.";else if(type==="weekdays")text="De segunda a sexta.";else if(type==="weekly")text=`Toda ${WEEKDAYS[d.getDay()].toLowerCase()}.`;else if(type==="custom_weekdays")text=days.length?days.join(", "):"Escolha os dias.";else if(type==="monthly")text=`Todo dia ${d.getDate()} do mês.`;$("#recurrencePreview").textContent=text;$("#recurrencePreview").classList.toggle("hidden",!rec)}
function renderExceptions(){$("#taskExceptionList").innerHTML=state.editExceptions.map((x,i)=>`<span class="exception-chip">🚫 ${new Date(x.exception_date+"T12:00").toLocaleDateString("pt-BR")}${x.reason?` • ${esc(x.reason)}`:""}<button type="button" data-remove-exception="${i}">×</button></span>`).join("")}
function renderTasks(){const from=isoDate(addDays(new Date(),-30)),to=isoDate(addDays(new Date(),30)),inst=taskInstances(from,to),c={done:0,missed:0,unexpected:0,planned:0};inst.filter(x=>x.date<=today()).forEach(x=>c[x.status]++);$("#taskSummaryCards").innerHTML=[["✅","Realizadas • 30 dias",c.done,"goodish"],["○","Não realizadas",c.missed,"badish"],["⚡","Imprevistos",c.unexpected,"warnish"],["🔁","Rotinas",state.tasks.filter(isRecurringTask).length,""]].map(x=>`<article class="metric-card ${x[3]}"><strong>${x[0]} ${x[2]}</strong><small>${x[1]}</small></article>`).join("");let rows=[];if(state.taskFilter==="today")rows=taskInstances(today(),today());else if(["done","missed","unexpected"].includes(state.taskFilter))rows=inst.filter(x=>x.status===state.taskFilter);else{const t=state.tasks.filter(x=>state.taskFilter!=="recurring"||isRecurringTask(x));rows=t.map(task=>({task,date:isRecurringTask(task)?nextOccurrence(task):(task.due_date||today()),status:isRecurringTask(task)?occurrenceStatus(task,nextOccurrence(task)||today()):effectiveTaskStatus(task),template:true}))}$("#taskList").innerHTML=rows.length?rows.map(r=>{const t=r.task,rec=isRecurringTask(t),s=r.status,can=!r.template||r.date===today();return`<article class="list-card">${can?`<button class="circle-check ${s==="done"?"checked":s==="unexpected"?"unexpected":""}" data-task-toggle="${t.id}" data-occurrence-date="${r.date}">${s==="done"?"✓":s==="unexpected"?"⚡":""}</button>`:`<span class="circle-check">${rec?"↻":""}</span>`}<div class="list-card-main"><div class="list-card-title">${esc(t.title)}</div><div class="list-card-meta"><span>${esc(t.category)}</span><span>📅 ${r.date?new Date(r.date+"T12:00").toLocaleDateString("pt-BR"):"—"}</span>${t.assigned_to?`<span>👤 ${esc(memberName(t.assigned_to))}</span>`:""}<span class="priority-badge ${t.priority||"normal"}">${t.priority==="urgent"?"Urgente":t.priority==="important"?"Importante":"Normal"}</span>${rec?`<span class="repeat-badge">🔁 ${esc(recurrenceText(t))}</span>`:`<span class="status-label ${s}">${statusText(s)}</span>`}</div>${rec&&state.taskExceptions.some(x=>x.task_id===t.id)?`<div class="tiny muted">📆 ${state.taskExceptions.filter(x=>x.task_id===t.id).length} data(s) pulada(s)</div>`:""}</div><div class="list-actions">${can?`<button class="icon-mini" data-task-unexpected="${t.id}" data-occurrence-date="${r.date}">⚡</button>`:""}<button class="icon-mini" data-edit-task="${t.id}">✎</button></div></article>`}).join(""):`<div class="empty-state">Nenhuma tarefa aqui.</div>`}
function openTask(id=null){state.editingTaskId=id;const t=id?state.tasks.find(x=>x.id===id):null;$("#taskDialogTitle").textContent=t?"Editar tarefa":"Nova tarefa";$("#taskTitle").value=t?.title||"";$("#taskCategory").value=t?.category||"🏠 Casa";$("#taskPriority").value=t?.priority||"normal";$("#taskRecurrence").value=t?.recurrence_type||"none";$("#taskDueDate").value=t?(isRecurringTask(t)?recurrenceStart(t):(t.due_date||today())):today();$("#taskRecurrenceEnd").value=t?.recurrence_end||"";$$("[data-recur-day]").forEach(x=>x.checked=(t?.recurrence_weekdays||[]).map(Number).includes(Number(x.dataset.recurDay)));$("#taskAssignedTo").value=t?.assigned_to||"";$("#taskNotes").value=t?.notes||"";$("#taskDone").checked=!!t?.is_done;$("#taskUnexpected").checked=!!t?.unforeseen;state.editExceptions=t?state.taskExceptions.filter(x=>x.task_id===t.id).map(x=>({...x})):[];renderExceptions();updateRecurrenceUI();$("#deleteTask").style.visibility=t?"visible":"hidden";openDialog("#taskDialog")}
async function saveTask(e){e.preventDefault();const rec=$("#taskRecurrence").value,start=$("#taskDueDate").value||today(),days=selectedRecurDays();if(rec==="custom_weekdays"&&!days.length)return toast("Escolha pelo menos um dia.");const recurring=rec!=="none",payload={board_id:state.board.id,title:$("#taskTitle").value.trim(),category:$("#taskCategory").value,priority:$("#taskPriority").value,due_date:recurring?null:start,recurrence_type:rec,recurrence_start:recurring?start:null,recurrence_end:recurring?($("#taskRecurrenceEnd").value||null):null,recurrence_weekdays:rec==="custom_weekdays"?days:null,assigned_to:$("#taskAssignedTo").value||null,is_done:recurring?false:$("#taskDone").checked,unforeseen:recurring?false:$("#taskUnexpected").checked,notes:$("#taskNotes").value.trim()||null,updated_at:new Date().toISOString()};let id=state.editingTaskId;if(state.mode==="demo"){if(id)Object.assign(state.tasks.find(x=>x.id===id),payload);else{id=crypto.randomUUID();state.tasks.push({...payload,id,created_by:state.user.id,created_at:new Date().toISOString()})}state.taskExceptions=state.taskExceptions.filter(x=>x.task_id!==id);state.editExceptions.forEach(x=>state.taskExceptions.push({...x,id:crypto.randomUUID(),task_id:id,board_id:state.board.id}));demoSave()}else{const r=id?await state.supabase.from("shared_tasks").update(payload).eq("id",id).select().single():await state.supabase.from("shared_tasks").insert({...payload,created_by:state.user.id}).select().single();if(r.error)return toast(r.error.message);id=r.data.id;await state.supabase.from("shared_task_exceptions").delete().eq("task_id",id);if(state.editExceptions.length)await state.supabase.from("shared_task_exceptions").insert(state.editExceptions.map(x=>({board_id:state.board.id,task_id:id,exception_date:x.exception_date,reason:x.reason||null,created_by:state.user.id})));await refreshAll(false)}closeDialog("#taskDialog");renderAll();toast("Tarefa salva.")}
async function toggleTask(id,mode,date){const t=state.tasks.find(x=>x.id===id);if(isRecurringTask(t)){const cur=taskOccurrence(t,date),payload={board_id:state.board.id,task_id:id,occurrence_date:date,is_done:mode==="done"?!cur?.is_done:false,unforeseen:mode==="unexpected"?!cur?.unforeseen:false,completed_by:mode==="done"?state.user.id:null,completed_at:mode==="done"?new Date().toISOString():null,updated_at:new Date().toISOString()};if(state.mode==="demo"){if(cur)Object.assign(cur,payload);else state.taskOccurrences.push({...payload,id:crypto.randomUUID()});demoSave()}else{await state.supabase.from("shared_task_occurrences").upsert(payload,{onConflict:"task_id,occurrence_date"});await refreshAll(false)}}else{const patch=mode==="unexpected"?{unforeseen:!t.unforeseen,is_done:false}:{is_done:!t.is_done,unforeseen:false};if(state.mode==="demo"){Object.assign(t,patch);demoSave()}else{await state.supabase.from("shared_tasks").update({...patch,updated_at:new Date().toISOString()}).eq("id",id);await refreshAll(false)}}renderAll()}
async function deleteTask(){const id=state.editingTaskId;if(!id)return;if(state.mode==="demo"){state.tasks=state.tasks.filter(x=>x.id!==id);state.taskOccurrences=state.taskOccurrences.filter(x=>x.task_id!==id);state.taskExceptions=state.taskExceptions.filter(x=>x.task_id!==id);demoSave()}else{await state.supabase.from("shared_tasks").delete().eq("id",id);await refreshAll(false)}closeDialog("#taskDialog");renderAll()}

function renderShopping(){const pending=state.shopping.filter(x=>!x.is_bought),bought=state.shopping.filter(x=>x.is_bought),est=pending.reduce((a,x)=>a+Number(x.estimated_price||0),0);$("#shoppingMetrics").innerHTML=[["🛒","Pendentes",pending.length,""],["✅","Comprados",bought.length,"goodish"],["💵","Estimativa",money(est),"money"],["👥","Com responsável",pending.filter(x=>x.assigned_to).length,""]].map(x=>`<article class="metric-card ${x[3]}"><strong>${x[0]} ${x[2]}</strong><small>${x[1]}</small></article>`).join("");let list=state.shopping;if(state.shoppingFilter==="pending")list=list.filter(x=>!x.is_bought);if(state.shoppingFilter==="bought")list=list.filter(x=>x.is_bought);$("#shoppingList").innerHTML=list.length?list.map(x=>`<article class="list-card"><button class="circle-check ${x.is_bought?"checked":""}" data-shopping-toggle="${x.id}">${x.is_bought?"✓":""}</button><div class="list-card-main"><div class="list-card-title">${esc(x.item_name)} ${x.quantity?`• ${esc(x.quantity)}`:""}</div><div class="list-card-meta"><span>${esc(x.category)}</span>${x.assigned_to?`<span>👤 ${esc(memberName(x.assigned_to))}</span>`:""}${x.estimated_price!=null?`<span>≈ ${money(x.estimated_price)}</span>`:""}${x.finance_entry_id?`<span>💰 lançado no Banquinho</span>`:""}</div></div><button class="icon-mini" data-edit-shopping="${x.id}">✎</button></article>`).join(""):`<div class="empty-state">Lista vazia.</div>`}
function openShopping(id=null){state.editingShoppingId=id;const x=id?state.shopping.find(y=>y.id===id):null;$("#shoppingDialogTitle").textContent=x?"Editar item":"Novo item";$("#shoppingName").value=x?.item_name||"";$("#shoppingQty").value=x?.quantity||"";$("#shoppingCategory").value=x?.category||"🛒 Mercado";$("#shoppingAssignedTo").value=x?.assigned_to||"";$("#shoppingEstimated").value=x?.estimated_price??"";$("#shoppingNotes").value=x?.notes||"";$("#deleteShopping").style.visibility=x?"visible":"hidden";openDialog("#shoppingDialog")}
async function saveShopping(e){e.preventDefault();const p={board_id:state.board.id,item_name:$("#shoppingName").value.trim(),quantity:$("#shoppingQty").value.trim()||null,category:$("#shoppingCategory").value,assigned_to:$("#shoppingAssignedTo").value||null,estimated_price:$("#shoppingEstimated").value?Number($("#shoppingEstimated").value):null,notes:$("#shoppingNotes").value.trim()||null,updated_at:new Date().toISOString()};if(state.mode==="demo"){if(state.editingShoppingId)Object.assign(state.shopping.find(x=>x.id===state.editingShoppingId),p);else state.shopping.unshift({...p,id:crypto.randomUUID(),is_bought:false,created_by:state.user.id,created_at:new Date().toISOString()});demoSave()}else{const q=state.editingShoppingId?state.supabase.from("shopping_items").update(p).eq("id",state.editingShoppingId):state.supabase.from("shopping_items").insert({...p,created_by:state.user.id});const{error}=await q;if(error)return toast(error.message);await refreshAll(false)}closeDialog("#shoppingDialog");renderAll()}
async function toggleShopping(id){const x=state.shopping.find(y=>y.id===id);if(!x)return;if(!x.is_bought){let financeId=null;if(Number(x.estimated_price||0)>0){const f={board_id:state.board.id,entry_date:today(),title:`Compra: ${x.item_name}`,category:x.category||"🛒 Mercado",kind:"expense",amount:Number(x.estimated_price),is_paid:true,notes:x.quantity?`Quantidade: ${x.quantity}`:null,created_by:state.user.id,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};if(state.mode==="demo"){financeId=crypto.randomUUID();state.finance.unshift({...f,id:financeId})}else{const r=await state.supabase.from("finance_entries").insert(f).select().single();if(r.error)return toast(r.error.message);financeId=r.data.id}}const patch={is_bought:true,bought_at:new Date().toISOString(),bought_by:state.user.id,finance_entry_id:financeId,updated_at:new Date().toISOString()};if(state.mode==="demo"){Object.assign(x,patch);demoSave()}else{await state.supabase.from("shopping_items").update(patch).eq("id",id);await refreshAll(false)}toast(financeId?"Comprado ✓ e lançado no Banquinho.":"Marcado como comprado.")}else{if(x.finance_entry_id){if(state.mode==="demo")state.finance=state.finance.filter(f=>f.id!==x.finance_entry_id);else await state.supabase.from("finance_entries").delete().eq("id",x.finance_entry_id)}const patch={is_bought:false,bought_at:null,bought_by:null,finance_entry_id:null,updated_at:new Date().toISOString()};if(state.mode==="demo"){Object.assign(x,patch);demoSave()}else{await state.supabase.from("shopping_items").update(patch).eq("id",id);await refreshAll(false)}}renderAll()}
async function deleteShopping(){const id=state.editingShoppingId;if(!id)return;const x=state.shopping.find(y=>y.id===id);if(x?.finance_entry_id){if(state.mode==="demo")state.finance=state.finance.filter(f=>f.id!==x.finance_entry_id);else await state.supabase.from("finance_entries").delete().eq("id",x.finance_entry_id)}if(state.mode==="demo"){state.shopping=state.shopping.filter(x=>x.id!==id);demoSave()}else{await state.supabase.from("shopping_items").delete().eq("id",id);await refreshAll(false)}closeDialog("#shoppingDialog");renderAll()}

function financeTotals(){const inc=state.finance.filter(x=>x.kind==="income"),exp=state.finance.filter(x=>x.kind==="expense"),received=inc.filter(x=>x.is_paid).reduce((a,x)=>a+Number(x.amount),0),spent=exp.filter(x=>x.is_paid).reduce((a,x)=>a+Number(x.amount),0),pending=exp.filter(x=>!x.is_paid).reduce((a,x)=>a+Number(x.amount),0);return{received,spent,pending,current:received-spent,projected:received-spent-pending}}
function monthKey(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-01`}
function billDueDate(b,base){const d=new Date(base.getFullYear(),base.getMonth(),1),last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(Number(b.due_day),last));return isoDate(d)}
function billPayment(b,month){return state.billPayments.find(x=>x.bill_id===b.id&&x.billing_month===month)}
function billRowsAround(days=40){const rows=[],now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1);for(const b of state.bills.filter(x=>x.is_active!==false)){for(let i=0;i<3;i++){const m=addMonths(start,i),mk=monthKey(m);if(b.start_month&&mk<b.start_month)continue;if(b.end_month&&mk>b.end_month)continue;const due=billDueDate(b,m),diff=Math.round((parseDate(due)-parseDate(today()))/86400000),pay=billPayment(b,mk);if((diff>=-31&&diff<=days)||(!pay&&diff<0))rows.push({bill:b,month:mk,due,diff,payment:pay})}}return rows.sort((a,b)=>a.due.localeCompare(b.due))}
function dueLabel(r){if(r.payment)return{cls:"ok",text:"Pago"};if(r.diff<0)return{cls:"overdue",text:`Atrasada ${Math.abs(r.diff)}d`};if(r.diff===0)return{cls:"soon",text:"Vence hoje"};if(r.diff<=Number(r.bill.warning_days??3))return{cls:"soon",text:`Vence em ${r.diff}d`};return{cls:"",text:`Vence em ${r.diff}d`}}

function notifyDueBillsOnEntry(){
  if(state.billAlertShown)return;
  const rows=billRowsAround(7).filter(r=>!r.payment&&(r.diff<0||r.diff<=Number(r.bill.warning_days??3)));
  if(!rows.length)return;
  state.billAlertShown=true;
  const first=rows[0],label=dueLabel(first);
  toast(`💸 ${first.bill.title}: ${label.text}`);
  if("Notification" in window&&Notification.permission==="granted"){
    new Notification("Nosso Tempo 💸",{body:rows.length===1?`${first.bill.title}: ${label.text}`:`${rows.length} contas precisam de atenção.`});
  }
}
function renderFinance(){const t=financeTotals();$("#financeMetrics").innerHTML=[["💵","Entradas",money(t.received),"money"],["🧾","Gastos pagos",money(t.spent),"badish"],["⏳","Pendentes",money(t.pending),"warnish"],["✨","Sobra atual",money(t.current),t.current>=0?"goodish":"badish"]].map(x=>`<article class="metric-card ${x[3]}"><strong>${x[0]} ${x[2]}</strong><small>${x[1]}</small></article>`).join("");const allBillRows=billRowsAround(35),rows=state.bills.map(b=>allBillRows.find(r=>r.bill.id===b.id&&!r.payment)||allBillRows.find(r=>r.bill.id===b.id)).filter(Boolean);$("#billList").innerHTML=rows.length?rows.map(r=>{const l=dueLabel(r);return`<article class="list-card"><button class="circle-check ${r.payment?"checked":""}" data-bill-pay="${r.bill.id}" data-billing-month="${r.month}" data-due-date="${r.due}">${r.payment?"✓":""}</button><div class="list-card-main"><div class="list-card-title">${esc(r.bill.title)}</div><div class="list-card-meta"><span>${money(r.bill.amount)}</span><span>📅 dia ${r.bill.due_day}</span>${r.bill.responsible_to?`<span>👤 ${esc(memberName(r.bill.responsible_to))}</span>`:""}<span class="due-badge ${l.cls}">${l.text}</span></div></div><button class="icon-mini" data-edit-bill="${r.bill.id}">✎</button></article>`}).join(""):`<div class="empty-state">Nenhuma conta recorrente.</div>`;const f=$("#financeFilter")?.value||"all";let list=[...state.finance];if(f==="pending")list=list.filter(x=>!x.is_paid);if(f==="paid")list=list.filter(x=>x.is_paid);if(f==="expense")list=list.filter(x=>x.kind==="expense");if(f==="income")list=list.filter(x=>x.kind==="income");$("#financeList").innerHTML=list.length?list.map(x=>`<article class="list-card finance-row ${x.kind}"><button class="circle-check ${x.is_paid?"checked":""}" data-finance-paid="${x.id}">${x.is_paid?"✓":""}</button><div class="list-card-main"><div class="list-card-title">${esc(x.title)}</div><div class="list-card-meta"><span>${esc(x.category)}</span><span>📅 ${new Date(x.entry_date+"T12:00").toLocaleDateString("pt-BR")}</span></div></div><div class="amount">${x.kind==="income"?"+":"−"} ${money(x.amount)}</div><button class="icon-mini" data-edit-finance="${x.id}">✎</button></article>`).join(""):`<div class="empty-state">Sem movimentações.</div>`}
