function petTaskTypes(p,date){return[...new Set([...PET_DEFAULT_TASKS,...state.petLogs.filter(x=>x.pet_id===p.id&&x.care_date===date).map(x=>x.task_type)])]}
function petLog(pid,date,type){return state.petLogs.find(x=>x.pet_id===pid&&x.care_date===date&&x.task_type===type)}
function healthTypeLabel(t){return({vaccine:"💉 Vacina",dewormer:"💊 Vermífugo",flea:"🪲 Antipulgas",vet:"🩺 Veterinário",weight:"⚖️ Peso",medicine:"💊 Medicamento",other:"✨ Outro"})[t]||t}
function renderPets(){const date=$("#petDate").value||today();$("#petDate").value=date;const done=state.pets.reduce((a,p)=>a+PET_DEFAULT_TASKS.filter(t=>petLog(p.id,date,t)?.is_done).length,0),expected=state.pets.length*PET_DEFAULT_TASKS.length,dueHealth=state.petHealth.filter(x=>x.next_due_date&&x.next_due_date<=isoDate(addDays(new Date(),30))).length;$("#petMetrics").innerHTML=[["🐾","Cuidados hoje",`${done}/${expected}`,"goodish"],["🐱","Pets",state.pets.length,""],["🩺","Saúde próxima",dueHealth,"warnish"],["💛","Meta","constância",""]].map(x=>`<article class="metric-card ${x[3]}"><strong>${x[0]} ${x[2]}</strong><small>${x[1]}</small></article>`).join("");$("#petGrid").innerHTML=state.pets.map(p=>`<article class="pet-card"><div class="pet-head"><div class="pet-avatar">${p.emoji||"🐱"}</div><div><h3>${esc(p.name)}</h3><small>${esc(p.species)} • ${esc(p.coat||"")}</small></div></div><div class="pet-care-list">${petTaskTypes(p,date).map(type=>{const l=petLog(p.id,date,type);return`<button class="care-toggle ${l?.is_done?"done":""}" data-pet-care="${p.id}" data-care-type="${esc(type)}">${l?.is_done?"✓ ":""}${esc(type)}</button>`}).join("")}</div><div class="pet-add-care"><input data-pet-custom-input="${p.id}" placeholder="Outro cuidado..."/><button class="btn secondary" data-add-pet-care="${p.id}">+</button></div></article>`).join("");const health=[...state.petHealth].sort((a,b)=>(a.next_due_date||"9999").localeCompare(b.next_due_date||"9999"));$("#petHealthList").innerHTML=health.length?health.map(h=>{const pet=state.pets.find(x=>x.id===h.pet_id),due=h.next_due_date,cls=due&&due<today()?"health-due":due&&due<=isoDate(addDays(new Date(),30))?"health-upcoming":"";return`<article class="list-card ${cls}"><div class="list-card-main"><div class="list-card-title">${esc(pet?.name||"Pet")} • ${healthTypeLabel(h.record_type)} • ${esc(h.title)}</div><div class="list-card-meta"><span>Feito: ${new Date(h.record_date+"T12:00").toLocaleDateString("pt-BR")}</span>${due?`<span>Próximo: ${new Date(due+"T12:00").toLocaleDateString("pt-BR")}</span>`:""}${h.weight_kg?`<span>⚖️ ${h.weight_kg} kg</span>`:""}</div></div><button class="icon-mini" data-edit-health="${h.id}">✎</button></article>`}).join(""):`<div class="empty-state">Nenhum registro de saúde.</div>`}
async function togglePetCare(pid,type){const date=$("#petDate").value,l=petLog(pid,date,type),next=!l?.is_done;if(state.mode==="demo"){if(l)l.is_done=next;else state.petLogs.push({id:crypto.randomUUID(),pet_id:pid,care_date:date,task_type:type,is_done:true,done_by:state.user.id});demoSave()}else{if(l)await state.supabase.from("pet_care_logs").update({is_done:next,done_by:next?state.user.id:null,done_at:next?new Date().toISOString():null}).eq("id",l.id);else await state.supabase.from("pet_care_logs").insert({board_id:state.board.id,pet_id:pid,care_date:date,task_type:type,is_done:true,done_by:state.user.id,done_at:new Date().toISOString()});await refreshAll(false)}renderAll()}
