function renderGoals(){const active=state.goals.filter(g=>g.status==="active"),completed=state.goals.filter(g=>g.status==="completed");$("#goalMetrics").innerHTML=[["🎯","Ativas",active.length,""],["✅","Concluídas",completed.length,"goodish"],["⏳","Com prazo",active.filter(g=>g.deadline).length,"warnish"],["💰","Financeiras",active.filter(g=>g.goal_type==="money").length,"money"]].map(x=>`<article class="metric-card ${x[3]}"><strong>${x[0]} ${x[2]}</strong><small>${x[1]}</small></article>`).join("");$("#goalGrid").innerHTML=state.goals.length?state.goals.map(g=>{const pct=Math.min(100,Math.round(Number(g.current_value)/Number(g.target_value)*100)),unit=g.goal_type==="money"?"R$":g.unit||"";return`<article class="goal-card"><div class="goal-top"><div><p class="eyebrow">${g.status==="completed"?"CONCLUÍDA":"META"}</p><h3>${esc(g.title)}</h3></div><strong>${pct}%</strong></div><div class="goal-progress"><i style="width:${pct}%"></i></div><div class="list-card-meta"><span>${g.goal_type==="money"?money(g.current_value):`${g.current_value} ${esc(unit)}`} / ${g.goal_type==="money"?money(g.target_value):`${g.target_value} ${esc(unit)}`}</span>${g.deadline?`<span>📅 ${new Date(g.deadline+"T12:00").toLocaleDateString("pt-BR")}</span>`:""}</div><div class="goal-actions"><div class="progress-inline"><input type="number" step="0.01" min="0" placeholder="+ progresso" data-goal-add-input="${g.id}"/><button class="btn secondary" data-goal-add="${g.id}">Adicionar</button></div><button class="icon-mini" data-edit-goal="${g.id}">✎</button></div></article>`}).join(""):`<div class="empty-state">Nenhuma meta criada.</div>`}
function openGoal(id=null){state.editingGoalId=id;const g=id?state.goals.find(x=>x.id===id):null;$("#goalDialogTitle").textContent=g?"Editar meta":"Nova meta";$("#goalTitle").value=g?.title||"";$("#goalType").value=g?.goal_type||"money";$("#goalUnit").value=g?.unit||"";$("#goalCurrent").value=g?.current_value??0;$("#goalTarget").value=g?.target_value||"";$("#goalDeadline").value=g?.deadline||"";$("#goalNotes").value=g?.notes||"";$("#deleteGoal").style.visibility=g?"visible":"hidden";openDialog("#goalDialog")}
async function saveGoal(e){e.preventDefault();const current=Number($("#goalCurrent").value||0),target=Number($("#goalTarget").value),p={board_id:state.board.id,title:$("#goalTitle").value.trim(),goal_type:$("#goalType").value,unit:$("#goalUnit").value.trim()||null,current_value:current,target_value:target,deadline:$("#goalDeadline").value||null,notes:$("#goalNotes").value.trim()||null,status:current>=target?"completed":"active",updated_at:new Date().toISOString()};if(state.mode==="demo"){if(state.editingGoalId)Object.assign(state.goals.find(x=>x.id===state.editingGoalId),p);else state.goals.push({...p,id:crypto.randomUUID(),created_by:state.user.id,created_at:new Date().toISOString()});demoSave()}else{const q=state.editingGoalId?state.supabase.from("goals").update(p).eq("id",state.editingGoalId):state.supabase.from("goals").insert({...p,created_by:state.user.id});const{error}=await q;if(error)return toast(error.message);await refreshAll(false)}closeDialog("#goalDialog");renderAll()}
async function addGoalProgress(id){const input=$(`[data-goal-add-input="${id}"]`),add=Number(input.value||0),g=state.goals.find(x=>x.id===id);if(!add)return;const next=Number(g.current_value)+add,patch={current_value:next,status:next>=Number(g.target_value)?"completed":"active",updated_at:new Date().toISOString()};if(state.mode==="demo"){Object.assign(g,patch);demoSave()}else{await state.supabase.from("goals").update(patch).eq("id",id);await refreshAll(false)}renderAll()}
