function openStock(id=null){state.editingStockId=id;const x=id?state.stock.find(y=>y.id===id):null;$("#stockDialogTitle").textContent=x?"Editar item":"Novo item";$("#stockName").value=x?.item_name||"";$("#stockCategory").value=x?.category||"✨ Outro";$("#stockUnit").value=x?.unit||"";$("#stockCurrent").value=x?.current_qty??"";$("#stockMin").value=x?.min_qty??"";$("#stockNotes").value=x?.notes||"";$("#deleteStock").style.visibility=x?"visible":"hidden";openDialog("#stockDialog")}
async function saveStock(e){e.preventDefault();const p={board_id:state.board.id,item_name:$("#stockName").value.trim(),category:$("#stockCategory").value,unit:$("#stockUnit").value.trim()||null,current_qty:Number($("#stockCurrent").value),min_qty:Number($("#stockMin").value),notes:$("#stockNotes").value.trim()||null,updated_by:state.user.id,updated_at:new Date().toISOString()};if(state.mode==="demo"){if(state.editingStockId)Object.assign(state.stock.find(x=>x.id===state.editingStockId),p);else state.stock.push({...p,id:crypto.randomUUID(),created_at:new Date().toISOString()});demoSave()}else{const q=state.editingStockId?state.supabase.from("inventory_items").update(p).eq("id",state.editingStockId):state.supabase.from("inventory_items").insert(p);const{error}=await q;if(error)return toast(error.message);await refreshAll(false)}closeDialog("#stockDialog");renderAll()}
