function isNoticeRead(id){return state.noticeReads.some(x=>x.notice_id===id&&x.user_id===state.user.id)}
function activeNotices(){return state.notices.filter(n=>!n.expires_at||n.expires_at>=today())}
function unreadNotices(){return activeNotices().filter(n=>n.created_by!==state.user.id&&!isNoticeRead(n.id))}
function renderNotices(){const list=activeNotices();$("#noticeList").innerHTML=list.length?list.map(n=>`<article class="notice-card ${n.priority==="important"?"important":""} ${!isNoticeRead(n.id)&&n.created_by!==state.user.id?"unread":""}"><p class="eyebrow">${n.priority==="important"?"IMPORTANTE":"RECADO"}</p><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="notice-meta"><span>por ${esc(memberName(n.created_by))}</span>${n.created_by!==state.user.id&&!isNoticeRead(n.id)?`<button class="small-btn" data-read-notice="${n.id}">Marcar lido</button>`:""}</div></article>`).join(""):`<div class="empty-state">Nenhum recado.</div>`;const u=unreadNotices().length;$("#noticeBadge").textContent=u;$("#noticeBadge").classList.toggle("hidden",!u)}
function openNotice(){$("#noticeForm").reset();openDialog("#noticeDialog")}
async function saveNotice(e){e.preventDefault();const p={board_id:state.board.id,title:$("#noticeTitle").value.trim(),body:$("#noticeBody").value.trim(),priority:$("#noticePriority").value,expires_at:$("#noticeExpires").value||null,created_by:state.user.id};if(state.mode==="demo"){state.notices.unshift({...p,id:crypto.randomUUID(),created_at:new Date().toISOString()});demoSave()}else{await state.supabase.from("notices").insert(p);await refreshAll(false)}closeDialog("#noticeDialog");renderAll()}
async function markNoticeRead(id){if(state.mode==="demo"){if(!isNoticeRead(id))state.noticeReads.push({notice_id:id,user_id:state.user.id,read_at:new Date().toISOString()});demoSave()}else{await state.supabase.from("notice_reads").upsert({board_id:state.board.id,notice_id:id,user_id:state.user.id,read_at:new Date().toISOString()},{onConflict:"notice_id,user_id"});await refreshAll(false)}renderAll()}
function showUnreadNotices(){const list=unreadNotices();if(!list.length)return;$("#unreadNoticeList").innerHTML=list.map(n=>`<article class="notice-card ${n.priority==="important"?"important":""}"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small class="muted">por ${esc(memberName(n.created_by))}</small></article>`).join("");openDialog("#unreadDialog")}
