function todayAvailabilityRows(){const d=today(),wd=parseDate(d).getDay();return state.members.map(m=>({member:m,blocks:state.availability.filter(b=>b.user_id===m.user_id&&(b.specific_date===d||(!b.specific_date&&Number(b.weekday)===wd)))}))}
