async function saveProfile(e){e.preventDefault();const n=$("#profileName").value.trim(),c=$("#profileColor").value,note=$("#profileNote").value.trim();if(state.mode==="demo"){Object.assign(state.members.find(m=>m.user_id===state.user.id),{display_name:n,profile_color:c,profile_note:note});demoSave()}else{await state.supabase.rpc("update_my_profile",{p_board_id:state.board.id,p_display_name:n,p_profile_color:c,p_profile_note:note});await refreshAll(false)}renderAll()}
