function setPage(page){state.page=page;$$("[data-app-page]").forEach(x=>x.classList.toggle("active",x.dataset.appPage===page));$$("[data-page]").forEach(x=>x.classList.toggle("active",x.dataset.page===page));$("#mobileFab").classList.toggle("hidden",page!=="calendar");if(page==="today")renderToday();window.scrollTo({top:0,behavior:"smooth"})}
