function downloadICS(){const date=state.activeDate.replaceAll("-",""),start=($("#planTime").value||"19:00").replace(":","")+"00",end=($("#planEndTime").value||$("#planTime").value||"20:00").replace(":","")+"00",title=($("#planTitle").value||"Nosso Tempo").replace(/,/g,"\\,"),ics=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Nosso Tempo//PT-BR","BEGIN:VEVENT",`UID:${crypto.randomUUID()}@nosso-tempo`,`DTSTART;TZID=America/Sao_Paulo:${date}T${start}`,`DTEND;TZID=America/Sao_Paulo:${date}T${end}`,`SUMMARY:${title}`,"BEGIN:VALARM","TRIGGER:-PT30M","ACTION:DISPLAY","DESCRIPTION:Lembrete Nosso Tempo","END:VALARM","END:VEVENT","END:VCALENDAR"].join("\r\n"),blob=new Blob([ics],{type:"text/calendar"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`nosso-tempo-${state.activeDate}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
