$$(".tab").forEach(b=>b.addEventListener("click",()=>{state.authMode=b.dataset.authTab;$$(".tab").forEach(x=>x.classList.toggle("active",x===b));$("#authSubmit").textContent=state.authMode==="login"?"Entrar":"Criar conta"}));
$("#authForm").addEventListener("submit",async e=>{e.preventDefault();const email=$("#authEmail").value.trim(),password=$("#authPassword").value;if(state.authMode==="signup"){const{data,error}=await state.supabase.auth.signUp({email,password});if(error)return toast(error.message);if(!data.session)return toast("Conta criada. Confirme o e-mail.");state.user=data.user}else{const{data,error}=await state.supabase.auth.signInWithPassword({email,password});if(error)return toast(error.message);state.user=data.user}await loadBoards()});
